<?php
define('NOREQUIREHTML',1);define('NOREQUIREMENU',1);
require_once __DIR__.'/lib/main.lib.php';require_once __DIR__.'/lib/portal.lib.php';require_once __DIR__.'/lib/operation_reports.lib.php';cpcc_portal_require_access($user);
$socid=cpcc_portal_customer_scope_id($db,$user,GETPOSTINT('socid'));$id=GETPOSTINT('id');
$sql="SELECT d.*,o.ref operation_ref,o.rowid operation_id FROM ".MAIN_DB_PREFIX."cpo_document d JOIN ".MAIN_DB_PREFIX."cpo_operation o ON o.rowid=d.fk_operation AND o.entity=d.entity WHERE d.entity=".(int)$conf->entity." AND d.rowid=".$id." AND o.fk_soc=".(int)$socid." AND o.status=1 AND o.customer_visible=1 AND d.visibility='customer_after_approval' AND d.review_status IN ('approved','final_received') AND d.is_current=1";
$res=$db->query($sql);$document=$res?$db->fetch_object($res):null;if(!$document)cpcc_portal_access_denied($user,'reports');$base=$conf->chinaplanetoperations->dir_output.'/documents/'.(int)$conf->entity.'/'.$document->operation_ref;$path=realpath($base.'/'.$document->stored_name);$root=realpath($base);if(!$path||!$root||strpos($path,rtrim($root,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR)!==0||!is_file($path))accessforbidden();
header('Content-Type: '.($document->mime_type?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.rawurlencode(basename($document->original_name)).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;
